using ModelContextProtocol.Server;
using System.Net.Http.Json;
using System.Text.Json;

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool(Name = "get_weather"),
     Description("Gets current weather for a location by latitude and longitude.")]
    public static async Task<string> GetWeather(
        IHttpClientFactory httpClientFactory,
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        using var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var current = json.GetProperty("current");

        var temp = current.GetProperty("temperature_2m").GetDouble();
        var wind = current.GetProperty("wind_speed_10m").GetDouble();

        return $"Temperature: {temp}°C, Wind: {wind} km/h";
    }

    [McpServerTool(Name = "get_weather_by_city"),
     Description("Gets current weather for a well-known city name.")]
    public static async Task<string> GetWeatherByCity(
        IHttpClientFactory httpClientFactory,
        [Description("City name, e.g. 'London' or 'New York'")] string city)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        // Geocode the city name first
        var geoUrl = $"v1/search?name={Uri.EscapeDataString(city)}&count=1";
        using var geoResponse = await client.GetAsync(
            $"https://geocoding-api.open-meteo.com/{geoUrl}");
        geoResponse.EnsureSuccessStatusCode();

        var geoJson = await geoResponse.Content.ReadFromJsonAsync<JsonElement>();
        if (!geoJson.TryGetProperty("results", out var results)
            || results.GetArrayLength() == 0)
        {
            return $"City '{city}' not found.";
        }

        var loc = results[0];
        var lat = loc.GetProperty("latitude").GetDouble();
        var lon = loc.GetProperty("longitude").GetDouble();
        var name = loc.GetProperty("name").GetString();

        return $"{name}: {await GetWeather(httpClientFactory, lat, lon)}";
    }
}

